<?php
class VitalSignController{public function index():void{view('vitals/index',['rows'=>VitalSign::all(),'adults'=>OlderAdult::all()]);}public function store():void{$peso=(float)$_POST['peso'];$talla=(float)$_POST['talla'];$imc=$talla>0?round($peso/($talla*$talla),2):0;VitalSign::create(['older_adult_id'=>$_POST['older_adult_id'],'presion_sistolica'=>$_POST['presion_sistolica'],'presion_diastolica'=>$_POST['presion_diastolica'],'frecuencia_cardiaca'=>$_POST['frecuencia_cardiaca'],'saturacion_oxigeno'=>$_POST['saturacion_oxigeno'],'temperatura'=>$_POST['temperatura'],'peso'=>$peso,'talla'=>$talla,'imc'=>$imc]);redirect('/SICAM/public/signos-vitales');}}
